def _get_poppler_path() -> str | None:
    """Return the path to poppler binaries on Windows, or None on Linux/macOS."""
    local = pathlib.Path("poppler") / "Library" / "bin"
    if local.exists():
        return str(local)
    return None

def pdf_to_images(pdf_path: str, dpi: int = 150) -> list[Image.Image]:
    poppler_path = _get_poppler_path()
    return convert_from_path(pdf_path, dpi=dpi, fmt="RGB", poppler_path=poppler_path)

